(async () => {
  const H = await import('/history/index.ts'); const S = await import('/state/index.ts');
  const w = S.useHistoryStore.getState().world.value; const n = H.worldNow();
  const beat = n.beats[n.beats.length - 1]; const slot = beat.body.slots[0];
  const cited = n.events[slot.cite].label;
  const before = { head: n.head.n, refused: w.status.refused, pending: w.status.pending };
  const tries = [
    ['uncited', { beat: beat.id, slot: 0, text: 'They say the wind turned at dusk.' }],
    ['names another label', { beat: beat.id, slot: 0, text: 'They say ' + cited + ' was seen with ' + n.names[w.now.owner] + '.' }],
    ['a slot the beat did not open (6)', { beat: beat.id, slot: 6, text: 'They say ' + cited + ' was here.' }],
    ['a beat this world never had', { beat: w.worldId, slot: 0, text: 'They say ' + cited + ' was here.' }],
  ];
  const out = [];
  for (const [what, body] of tries) {
    const r = await window.seed.world.append(w.worldId, { kind: 'rumor', body, seen: n.head.n });
    out.push({ what, text: body.text, slot: body.slot, result: r.ok ? 'written ' + r.value.id : r.error.code + ': ' + r.error.message });
  }
  await new Promise(r => setTimeout(r, 1500));
  const w2 = S.useHistoryStore.getState().world.value;
  return JSON.stringify({ before, after: { head: H.worldNow().head.n, refused: w2.status.refused, pending: w2.status.pending }, role: w2.status.role, out }, null, 1);
})()
